def _pos32(h, l, c, idx):
    """Close position in the last-32-M15-bar range
    [0, 1]: (entry close - lowest low of bars
    idx-31..idx) / (highest high - lowest low of
    the same bars); None when unavailable."""
    if idx < 31:
        return None
    hh = float(np.max(h[idx - 31:idx + 1]))
    ll = float(np.min(l[idx - 31:idx + 1]))
    if hh <= ll:
        return None
    return (float(c[idx]) - ll) / (hh - ll)


def _trade_outcome(bars, sym, entry_s, side, dist_pips):
    """(exit_epoch, net25) for one candidate at a
    FIXED pip distance; exit/net are None while the
    trade is unresolved in the available bars and
    the 48h cap bar is not yet present. Locked
    replay form (SL-first in one bar)."""
    ts, _o, h, l, c = bars
    idx = int(np.searchsorted(ts, entry_s - 900))
    if idx >= len(ts) or ts[idx] != entry_s - 900:
        return None, None
    ph = h[idx + 1:idx + 1 + MAXHOLD_BARS]
    pl = l[idx + 1:idx + 1 + MAXHOLD_BARS]
    fwd = ts[idx + 1:idx + 1 + MAXHOLD_BARS]
    entry = float(c[idx])
    pip = _pip_of(sym)
    dist_price = dist_pips * pip
    if side > 0:
        sl_hit = pl <= entry - dist_price
        tp_hit = ph >= entry + TP_FRAC * dist_price
    else:
        sl_hit = ph >= entry + dist_price
        tp_hit = pl <= entry - TP_FRAC * dist_price
    isl = int(np.argmax(sl_hit)) if sl_hit.any()\
        else 10 ** 9
    itp = int(np.argmax(tp_hit)) if tp_hit.any()\
        else 10 ** 9
    if isl == 10 ** 9 and itp == 10 ** 9:
        if len(ph) >= MAXHOLD_BARS:
            gross = side * (float(c[idx + MAXHOLD_BARS])
                            - entry) / pip
            return entry_s + MAX_HOLD * 3600,\
                gross - COST_PIPS
        return None, None
    if isl <= itp:
        return int(fwd[isl]) + 900, -dist_pips - COST_PIPS
    return int(fwd[itp]) + 900,\
            TP_FRAC * dist_pips - COST_PIPS


def _slot_rows(T, m15_bars, eqs=None):
    """Candidate rows for one slot: for every symbol
    with an available entry bar, both sides, each
    carrying its own equation's score / in-band flag
    / fixed distance. Canonical order: symbol index,
    side desc (BUY first)."""
    if eqs is None:
        eqs = EQUATIONS
    rows = []
    hour = (T % 86400) // 3600
    for sym in SYMBOLS:
        bars = m15_bars.get(sym)
        if bars is None:
            continue
        ts, _o, h, l, c = bars
        idx = int(np.searchsorted(ts, T - 900))
        if idx >= len(ts) or ts[idx] != T - 900\
                or idx < 31:
            continue
        pos = _pos32(h, l, c, idx)
        if pos is None:
            continue
        eq = eqs[sym]
        lo, hi = BANDS[eq["band"]]
        entry_px = float(c[idx])
        for side in (1, -1):
            adj = pos if side > 0 else 1.0 - pos
            bucket = 0 if adj < BUCKET_E1 else\
                (1 if adj < BUCKET_E2 else 2)
            score = float(eq["cells"].get(
                (hour, side, bucket), eq["prior"]))
            xp, net = _trade_outcome(bars, sym, T, side,
                                     eq["dist"])
            rows.append({
                "sym": sym, "side": side,
                "dist": eq["dist"],
                "score": score,
                "in_band": bool(lo < adj < hi),
                "entry_px": entry_px,
                "pos_adj": float(adj),
                "exit": xp, "net": net,
                "entry_s": int(T)})
    return rows


def _margin(row):
    return row["score"] - EQUATIONS[row["sym"]]["tau"]


GOV_THETA = -40.0
PROT_T = 43.0 / 66.0  # protection clause threshold:
# GOV-A's weakest DISC-year win rate (2020, 43/66),
# fitted on DISC at R4-033 stage 1


class _Book:
    """One ingredient book of R444-ARB: the December
    per-symbol fill (win ranking) over its own 28
    equations, with its own blocking ledger; with
    governor_theta set it carries the GOV-2 causal
    realised-path governor (the R422 form verbatim);
    with prot_T set it additionally carries the
    worst-year protection clause at the firing
    decision (the R4-033 form).
    process() returns the recorded pick or None."""

    def __init__(self, equations, governor_theta=None,
                 prot_T=None):
        self.equations = equations
        self.gov_theta = governor_theta
        self.prot_T = prot_T
        self.max_exit = {}
        self.picks = []
        self.gov_firings = 0
        self.gov_triggers = 0
        self.gov_refusals = 0
        self.year_state = {}

    def _record(self, row, ts, tier):
        pick = {"sym": row["sym"], "entry_s": int(ts),
                "side": int(row["side"]),
                "dist": float(row["dist"]),
                "entry_px": float(row["entry_px"]),
                "score": float(row["score"]),
                "tier": int(tier),
                "layer": "persym",
                "exit": row["exit"], "net": row["net"]}
        self.picks.append(pick)
        if self.prot_T is not None\
                and row["net"] is not None:
            yr = _dt.datetime.fromtimestamp(
                int(ts), tz=_dt.timezone.utc).year
            st = self.year_state.setdefault(
                yr, [0, 0])
            st[0] += 1
            if row["net"] > 0:
                st[1] += 1
        if row["exit"] is None:
            self.max_exit[row["sym"]] = float("inf")
        else:
            self.max_exit[row["sym"]] = max(
                self.max_exit.get(row["sym"], -1),
                int(row["exit"]))
        return pick

    def to_dict(self):
        return {
            "max_exit": {k: ("inf" if v == float("inf")
                             else v)
                         for k, v in self.max_exit.items()},
            "picks": self.picks,
            "gov_firings": self.gov_firings,
            "gov_triggers": self.gov_triggers,
            "gov_refusals": self.gov_refusals,
            "year_state": {str(k): v for k, v in
                           self.year_state.items()}}

    def from_dict(self, d):
        self.max_exit = {k: (float("inf") if v == "inf"
                             else int(v))
                         for k, v in d.get("max_exit",
                                           {}).items()}
        self.picks = d.get("picks", [])
        self.gov_firings = d.get("gov_firings", 0)
        self.gov_triggers = d.get(
            "gov_triggers", 0)
        self.gov_refusals = d.get(
            "gov_refusals", 0)
        self.year_state = {
            int(k): list(v) for k, v in
            d.get("year_state", {}).items()}

    def resolve_pending(self, m15_bars):
        for pick in self.picks:
            if pick["exit"] is not None:
                continue
            bars = m15_bars.get(pick["sym"])
            if bars is None:
                continue
            xp, net = _trade_outcome(
                bars, pick["sym"], pick["entry_s"],
                pick["side"], pick["dist"])
            if xp is None:
                continue
            pick["exit"] = int(xp)
            pick["net"] = float(net)
            ex = [p["exit"] if p["exit"] is not None
                  else float("inf")
                  for p in self.picks
                  if p["sym"] == pick["sym"]]
            self.max_exit[pick["sym"]] = max(ex)

    def process(self, ts, rows):
        if not rows:
            return None
        eqs = self.equations
        by_sym = {}
        for i, r in enumerate(rows):
            if self.max_exit.get(r["sym"], -1) > ts:
                continue
            by_sym.setdefault(r["sym"], []).append(i)
        if not by_sym:
            return None

        def margin(row):
            return row["score"] - eqs[row["sym"]]["tau"]

        def best(idxs, keyf):
            return min(idxs, key=lambda i: (
                -keyf(rows[i]), SYM_IDX[rows[i]["sym"]],
                0 if rows[i]["side"] > 0 else 1))

        def select(syms):
            band_best, any_best = {}, {}
            for sym in syms:
                idxs = by_sym[sym]
                br = [i for i in idxs if rows[i]["in_band"]]
                if br:
                    band_best[sym] = best(
                        br, lambda r: r["score"])
                any_best[sym] = best(idxs, margin)
            firing = {s: i for s, i in band_best.items()
                      if rows[i]["score"] >= eqs[s]["tau"]}
            if firing:
                return best(list(firing.values()),
                            lambda r: r["score"]), 1
            if band_best:
                return best(list(band_best.values()),
                            margin), 2
            return best(list(any_best.values()), margin), 3

        pick, tier = select(list(by_sym.keys()))
        if self.gov_theta is not None:
            exited = [(p["exit"], k, p)
                      for k, p in enumerate(self.picks)
                      if p["exit"] is not None
                      and p["net"] is not None
                      and p["exit"] <= ts]
            if exited:
                exited.sort(key=lambda t: (t[0], t[1]))
                state = sum(t[2]["net"] for t in exited[-5:])
                if state <= self.gov_theta:
                    ws = rows[pick]["sym"]

                    def own_state(sym):
                        own = [t for t in exited
                               if t[2]["sym"] == sym]
                        return sum(t[2]["net"]
                                   for t in own[-3:])\
                            if own else 0.0

                    clean = [s for s in by_sym
                             if s != ws
                             and own_state(s) >= 0.0]
                    if clean:
                        pick2, tier2 = select(clean)
                        self.gov_triggers += 1
                        refuse = False
                        if (self.prot_T is not None
                                and pick2 != pick):
                            yr = _dt.datetime.fromtimestamp(int(ts), tz=_dt.timezone.utc).year
                            st = self.year_state.get(yr)
                            if (st is not None
                                    and st[0] >= 1
                                    and st[1] / st[0]
                                    <= self.prot_T):
                                pw = (rows[pick]
                                      ["net"]
                                      is not None
                                      and rows[pick]
                                      ["net"] > 0)
                                rw = (rows[pick2]
                                      ["net"]
                                      is not None
                                      and rows[pick2]
                                      ["net"] > 0)
                                if pw and not rw:
                                    refuse = True
                        if refuse:
                            self.gov_refusals += 1
                        else:
                            pick, tier = pick2, tier2
                            self.gov_firings += 1
        return self._record(rows[pick], ts, tier)


class FillState:
    """The R444-ARB arbitrated fill. Slots are
    processed in chronological order; PH-C's book
    and GOVPROT-A's book are settled in parallel (each
    keeps its own blocking ledger), and the kept
    pick is chosen by the frozen arbitration."""

    def __init__(self):
        self.phc = _Book(EQUATIONS_PHC)
        self.govprot = _Book(EQUATIONS,
                             governor_theta=
                             GOV_THETA,
                             prot_T=PROT_T)
        self.max_exit = {}
        self.picks = []
        self.arb_census = {"identical": 0, "phc": 0,
                           "govprot": 0, "tie_govprot": 0,
                           "solo": 0}
        self.ev = {e: {"slots_total": 0, "picks": 0,
                       "unfilled_no_rows": 0,
                       "unfilled_all_blocked": 0,
                       "tier2": 0, "tier3": 0}
                   for e in ("disc", "audit")}

    def to_dict(self):
        return {"phc": self.phc.to_dict(),
                "govprot": self.govprot.to_dict(),
                "max_exit": {k: ("inf" if v == float("inf")
                                 else v)
                             for k, v in
                             self.max_exit.items()},
                "picks": self.picks,
                "arb_census": self.arb_census}

    def from_dict(self, d):
        self.phc.from_dict(d.get("phc", {}))
        self.govprot.from_dict(d.get("govprot", {}))
        self.max_exit = {k: (float("inf") if v == "inf"
                             else int(v))
                         for k, v in d.get("max_exit",
                                           {}).items()}
        self.picks = d.get("picks", [])
        self.arb_census = d.get(
            "arb_census",
            {"identical": 0, "phc": 0, "govprot": 0,
             "tie_govprot": 0, "solo": 0})

    def resolve_pending(self, m15_bars):
        self.phc.resolve_pending(m15_bars)
        self.govprot.resolve_pending(m15_bars)

    def process_slot(self, ts, era, m15_bars):
        e = self.ev[era]
        e["slots_total"] += 1
        rows_p = _slot_rows(ts, m15_bars, EQUATIONS_PHC)
        rows_g = _slot_rows(ts, m15_bars, EQUATIONS)
        a = self.phc.process(ts, rows_p)
        b = self.govprot.process(ts, rows_g)
        if a is None and b is None:
            e["unfilled_no_rows"] += 1
            return []
        if a is None or b is None:
            chosen = a if a is not None else b
            chosen["source"] = "PHC" if a is not None\
                else "GOVPROT"
            self.arb_census["solo"] += 1
        elif a["sym"] == b["sym"]\
                and a["side"] == b["side"]\
                and a["net"] is not None\
                and b["net"] is not None\
                and abs(a["net"] - b["net"]) < 1e-9:
            chosen = a
            chosen["source"] = "BOTH"
            self.arb_census["identical"] += 1
        else:
            pa = PREFS_PHC.get(a["sym"], 0.0)
            pb = PREFS_GOVPROT.get(b["sym"], 0.0)
            if pa > pb:
                chosen = a
                chosen["source"] = "PHC"
                self.arb_census["phc"] += 1
            elif pb > pa:
                chosen = b
                chosen["source"] = "GOVPROT"
                self.arb_census["govprot"] += 1
            else:
                chosen = b
                chosen["source"] = "GOVPROT"
                self.arb_census["tie_govprot"] += 1
        self.picks.append(chosen)
        if chosen["exit"] is None:
            self.max_exit[chosen["sym"]] = float("inf")
        else:
            self.max_exit[chosen["sym"]] = max(
                self.max_exit.get(chosen["sym"], -1),
                int(chosen["exit"]))
        if chosen["tier"] == 2:
            e["tier2"] += 1
        elif chosen["tier"] == 3:
            e["tier3"] += 1
        e["picks"] += 1
        return [chosen]




def _state_path():
    from core.new8_candidate import default_state_path
    return default_state_path(SYSTEM_NAME)


def _bars_from_frame(df):
    """App frame (DataFrame with a time column and
    OHLC) -> (ts, o, h, l, c) numpy arrays sorted by
    time."""
    if df is None or not len(df):
        return None
    try:
        tcol = next(c for c in df.columns
                    if c.lower() in ("datetime", "time",
                                     "timestamp"))
        ts = (pd.to_datetime(df[tcol], utc=True)
              .astype("int64") // 10 ** 9).to_numpy(np.int64)
        o = df["Open"].to_numpy(np.float64)
        h = df["High"].to_numpy(np.float64)
        l = df["Low"].to_numpy(np.float64)
        c = df["Close"].to_numpy(np.float64)
    except Exception:
        return None
    order = np.argsort(ts, kind="stable")
    return (ts[order], o[order], h[order], l[order],
            c[order])


class _Form:
    """The slot stream settled through the R444-ARB
    fill. Persisted: the fill state (blocking
    ledger, picks), the delivered ledger and the
    processed checks."""

    def __init__(self, path=None):
        self.path = path or _state_path()
        self.fill = DecStackFillState()
        self.delivered = []
        self.processed = []
        self._load()

    def _load(self):
        import json
        if not self.path or not os.path.exists(self.path):
            return
        try:
            with open(self.path) as fh:
                d = json.load(fh)
        except Exception:
            return
        self.processed = d.get("processed", [])
        if "fill" in d:
            self.fill.from_dict(d["fill"])
        out = []
        for r in d.get("delivered", []):
            r = dict(r)
            for k in ("check", "entry_time", "exit_time",
                      "entry_candle"):
                if r.get(k) is not None:
                    r[k] = pd.Timestamp(r[k])
            out.append(r)
        self.delivered = out

    def save(self):
        import json
        if not self.path:
            return
        os.makedirs(os.path.dirname(
            os.path.abspath(self.path)), exist_ok=True)

        def ser(rows):
            out = []
            for r in rows:
                dd = dict(r)
                for k in ("check", "entry_time",
                          "exit_time", "entry_candle"):
                    if dd.get(k) is not None:
                        dd[k] = pd.Timestamp(
                            dd[k]).isoformat()
                out.append(dd)
            return out
        with open(self.path, "w") as fh:
            json.dump({"system": SYSTEM_NAME,
                       "fill": self.fill.to_dict(),
                       "delivered": ser(self.delivered),
                       "processed": self.processed}, fh)

    def step(self, frames, check_time_utc, m15_frames,
             open_symbols=(), m5_frames=None):
        chk = pd.Timestamp(check_time_utc)
        if str(chk) in self.processed:
            return [r for r in self.delivered
                    if pd.Timestamp(r["check"]) == chk]
        T = int(chk.timestamp())
        T -= T % 3600  # entries fire at H:00 UTC
        if m15_frames is None:
            m15_frames = fetch_cycle94o_m15_frames()
        m15_bars = {}
        for sym in SYMBOLS:
            b = _bars_from_frame(
                m15_frames.get(sym) if m15_frames else None)
            if b is not None:
                m15_bars[sym] = b
        self.fill.resolve_pending(m15_bars)
        era = "disc" if _dt.datetime.utcfromtimestamp(
            T).year <= 2023 else "audit"
        picks = self.fill.process_slot(T, era,
                                       m15_bars)
        entry_candle = pd.Timestamp(
            _dt.datetime.utcfromtimestamp(T))
        out = []
        for p in picks:
            r = p
            dd = {"check": chk, "symbol": r["sym"],
                  "direction": "BUY" if r["side"] > 0
                  else "SELL",
                  "entry_candle": entry_candle,
                  "entry_time": entry_candle,
                  "entry_px": float(r["entry_px"]),
                  "tp_pips": float(TP_FRAC * r["dist"]),
                  "sl_pips": float(r["dist"]),
                  "exit_time": entry_candle
                  + pd.Timedelta(hours=MAX_HOLD),
                  "dist": float(r["dist"]),
                  "layer": "persym",
                  "system": SYSTEM_NAME}
            self.delivered.append(dd)
            out.append(dd)
        self.processed.append(str(chk))
        self.save()
        return out


_STATE = None


def _state():
    global _STATE
    if _STATE is None:
        _STATE = _Form()
    return _STATE


def load_state_form(path=None):
    if path is not None:
        return _Form(path=path)
    return _state()


def is_cycle94o_check_time(ts) -> bool:
    t = pd.Timestamp(ts)
    return t.hour in CYCLE94O_CHECK_HOURS and t.minute == 0


def panel_entries(frames: dict, check_time_utc,
                  m15_frames: dict | None = None,
                  open_symbols=(),
                  m5_frames: dict | None = None
                  ) -> pd.DataFrame:
    form = _state()
    out = form.step(frames, check_time_utc, m15_frames,
                    open_symbols, m5_frames)
    if isinstance(out, pd.DataFrame):
        return out
    if not out:
        return pd.DataFrame()
    return pd.DataFrame(out)


def walk_ledger():
    """The delivered cycle94n stream."""
    return [dict(r) for r in _state().delivered]


def fetch_cycle94o_m15_frames(state=None):
    from core.cycle78i_best import fetch_cycle78i_m15_frames
    return fetch_cycle78i_m15_frames()


def evaluate_cycle94o_signals(frames: dict,
                                check_time_utc,
                                m15_frames: dict | None
                                = None):
    return panel_entries(frames, check_time_utc,
                         m15_frames)


def select_cycle94o_entries(signals: pd.DataFrame,
                              open_symbols=()
                              ) -> pd.DataFrame:
    if signals is None or not len(signals):
        return signals
    return signals


# ---- RR12 R024 composed layer: BMR + DENS + RW-ADD over ARB2 ----
BMR_DIST_MIN = 30.0  # frozen at slate: DISC q75 of
# CTRL12N losing-pick distances (fixed pips; the
# loser-distance quantiles collapse at the top rung,
# q75 = q90 = max = 30.00)
DENS_DIST_MIN = 30.0  # frozen at slate: DISC q90 --
# the same collapsed class line; the -32.50
# pair-forming class lives at this distance


def _iso_week3(ts):
    return _dt.datetime.utcfromtimestamp(
        int(ts)).isocalendar()[:2]


class DecStackFillState:
    """The RR12 R024 DSTACK-N book: R444-ARB2 settled by
    the shipped arbitrated FillState at the NEW-LAW walk
    (TP = 2 x SL), composed with (a) BMR -- when the
    arbitrated recorded pick is a loss AND either its
    distance is at or above BMR_DIST_MIN (BRA arm) or
    it extends a consecutive-loss run of the composed
    MAIN stream to >= 2 (BLK arm, any distance -- block
    membership is the anatomy), the recorded pick is
    replaced by the best same-slot alternative row
    (union of the slot's two equation sets' rows at the
    NEW-LAW walk) with net > 0, strictly smaller
    distance, a different symbol, and unblocked in this
    composed book's recorded-pick ledger; (b) DENS --
    a BRA-qualifying loss at distance >= DENS_DIST_MIN
    with NO alternative row is dropped (not recorded),
    thinning the density of the -32.50 pair-forming
    class; a dropped pick enters neither the recorded
    stream, the week ledger, nor the run state, and
    the slot yields no add; (c) RW-ADD -- after the
    slot's main pick is recorded, if this book's
    running net in the pick's ISO week is < 0, one
    second pick is added at the same slot
    (highest-score row, net > 0, symbol unblocked in
    the recorded-pick ledger). The replacement trigger
    and the loss-run state read the composed MAIN
    stream only, and the replacement is decided before
    the slot's add, so the adds layer cannot clear the
    trigger. Only recorded picks change; the
    ingredient books settle their own ledgers first
    (the ARB2 composition precedent)."""

    def __init__(self):
        self.arb = FillState()
        self.picks = []
        self.rec_exit = {}
        self.run_net = {}
        self.main_run = 0
        self.census = {"bmr_bra": 0, "bmr_blk": 0,
                       "bmr_replace": 0, "bmr_no_alt": 0,
                       "dens_drop": 0, "adds": 0}

    # -- persistence (candidate _Form) --
    def to_dict(self):
        return {"arb": self.arb.to_dict(),
                "picks": self.picks,
                "rec_exit": {k: ("inf" if v == float("inf")
                                 else int(v))
                             for k, v in
                             self.rec_exit.items()},
                "run_net": {f"{k[0]}-{k[1]}": v
                            for k, v in
                            self.run_net.items()},
                "main_run": self.main_run,
                "census": self.census}

    def from_dict(self, d):
        self.arb.from_dict(d.get("arb", {}))
        self.picks = d.get("picks", [])
        self.rec_exit = {k: (float("inf") if v == "inf"
                             else int(v))
                         for k, v in d.get("rec_exit",
                                            {}).items()}
        self.run_net = {}
        for k, v in d.get("run_net", {}).items():
            y, w = k.split("-")
            self.run_net[(int(y), int(w))] = v
        self.main_run = d.get("main_run", 0)
        self.census = d.get("census", self.census)

    def resolve_pending(self, m15_bars):
        self.arb.resolve_pending(m15_bars)

    # -- composed bookkeeping --
    def _unblocked(self, sym, T):
        return self.rec_exit.get(sym, -1) <= T

    def _rows_union(self, T, bars):
        seen, out = set(), []
        for eqs in (EQUATIONS_PHC, EQUATIONS):
            for r in _slot_rows(T, bars, eqs):
                key = (r["sym"], int(r["side"]),
                       float(r["dist"]))
                if key in seen:
                    continue
                seen.add(key)
                out.append(r)
        return out

    @staticmethod
    def _rank(rows):
        return sorted(rows, key=lambda r: (
            -float(r["score"]), float(r["dist"]),
            SYM_IDX[r["sym"]],
            0 if r["side"] > 0 else 1))

    def _best_alt(self, T, rows, dist_max, skip_sym):
        cand = [r for r in rows
                if r["net"] is not None
                and float(r["net"]) > 0
                and float(r["dist"]) < dist_max
                and r["sym"] != skip_sym
                and self._unblocked(r["sym"], T)]
        return self._rank(cand)[0] if cand else None

    def _best_add(self, T, rows):
        cand = [r for r in rows
                if r["net"] is not None
                and float(r["net"]) > 0
                and self._unblocked(r["sym"], T)]
        return self._rank(cand)[0] if cand else None

    def _record(self, row, T, source, tier, arb_source=None):
        pick = {"sym": row["sym"], "entry_s": int(T),
                "side": int(row["side"]),
                "dist": float(row["dist"]),
                "entry_px": float(row["entry_px"]),
                "score": float(row["score"]),
                "tier": int(tier),
                "layer": "persym",
                "exit": row["exit"], "net": row["net"],
                "source": source}
        if arb_source is not None:
            pick["arb_source"] = arb_source
        self.picks.append(pick)
        if row["exit"] is None:
            self.rec_exit[row["sym"]] = float("inf")
        else:
            self.rec_exit[row["sym"]] = max(
                self.rec_exit.get(row["sym"], -1),
                int(row["exit"]))
        wk = _iso_week3(T)
        self.run_net[wk] = self.run_net.get(wk, 0.0)\
            + float(row["net"] or 0.0)
        return pick

    def process_slot(self, T, era, bars):
        out = self.arb.process_slot(T, era, bars)
        if not out:
            return []
        chosen = out[0]
        rows = None
        main = chosen
        dropped = False
        if chosen["net"] is not None\
                and float(chosen["net"]) <= 0:
            bra = float(chosen["dist"]) >= BMR_DIST_MIN
            blk = self.main_run >= 1
            if bra or blk:
                if bra:
                    self.census["bmr_bra"] += 1
                if blk:
                    self.census["bmr_blk"] += 1
                rows = self._rows_union(T, bars)
                alt = self._best_alt(
                    T, rows, float(chosen["dist"]),
                    chosen["sym"])
                if alt is not None:
                    main = {"sym": alt["sym"],
                            "entry_s": int(T),
                            "side": int(alt["side"]),
                            "dist": float(alt["dist"]),
                            "entry_px": float(
                                alt["entry_px"]),
                            "score": float(alt["score"]),
                            "tier": int(chosen["tier"]),
                            "layer": "persym",
                            "exit": alt["exit"],
                            "net": alt["net"],
                            "source": "BMR",
                            "arb_source":
                                chosen.get("source")}
                    self.census["bmr_replace"] += 1
                else:
                    self.census["bmr_no_alt"] += 1
                    if bra and float(chosen["dist"])\
                            >= DENS_DIST_MIN:
                        self.census["dens_drop"] += 1
                        dropped = True
        if dropped:
            return []
        rec = self._record(main, T, main.get(
            "source", "ARB"), int(main["tier"]),
            main.get("arb_source"))
        if float(main["net"] or 0.0) <= 0:
            self.main_run += 1
        else:
            self.main_run = 0
        made = [rec]
        wk = _iso_week3(T)
        if self.run_net.get(wk, 0.0) < 0:
            if rows is None:
                rows = self._rows_union(T, bars)
            add = self._best_add(T, rows)
            if add is not None:
                rec2 = self._record(
                    add, T, "RWADD", int(main["tier"]))
                self.census["adds"] += 1
                made.append(rec2)
        return made
